# Pre-review quality refinements: replace unrelated distractors with neighboring
# concepts and realistic category/assumption errors. Answer IDs are unchanged.
def R(n,option,text,explanation):
 q=next(q for q in QUESTIONS if q['id']==f'W01-L02-Q-{n:03}')
 oid=q['id']+f'-o{option}'
 next(o for o in q['options'] if o['id']==oid)['text']=text
 q['solution']['optionExplanations'][oid]=explanation
